// This block sends menu information to WebExtensions.
const messageId = element.id;
const subject = {
  menu: popup,
  tab: popup.documentGlobal,
  onHeaderPaneLink: true,
  linkText: messageId,
  linkUrl: `mid:${messageId.substring(1, messageId.length - 1)}`,
  pageUrl: getMessagePaneBrowser().contentDocument?.URL,
};
subject.wrappedJSObject = subject;
Services.obs.notifyObservers(subject, "on-build-contextmenu");

if (contextData.onHeaderPaneLink && extension.hasPermission("messagesRead")) {
  info.linkText = contextData.linkText;
  info.linkUrl = contextData.linkUrl;
}

  await subtest_message_panes(
    ["accountsRead", "messagesRead"],
    "header_pane_link",
    gExpectedInfo
  );
});
add_task(async function test_message_panes_no_accounts_permission() {
  return subtest_message_panes(
    ["messagesRead"],
    "header_pane_link",
    gExpectedInfo
  );
});
add_task(async function test_message_panes_no_messages_permission() {
  return subtest_message_panes(["accountsRead"], "header_pane_link");
});
add_task(async function test_message_panes_no_permissions() {
  return subtest_message_panes([], "header_pane_link");
});
